// update is Update's write, with the server-owned fields outputPaths names
// (UpdateWithOutputOnly) merged into its patch.
func (r *GraphQLWebhookRepository) update(ctx context.Context, in *hooksv1.Webhook, paths, outputPaths []string) (*hooksv1.Webhook, error) {
	ids, err := repox.SplitName(in.GetName(), "webhooks")
	if err != nil {
		return nil, err
	}
	id := ids[len(ids)-1]
	row, err := r.Svc.Query.HooksV1.Webhooks.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	existingPB := webhookFromRow(row)
	merged := proto.Clone(existingPB).(*hooksv1.Webhook)
	applyWebhookMask(merged, in, paths)
	if h := r.Hooks.BeforeUpdate; h != nil {
		if err := h(ctx, existingPB, merged, paths); err != nil {
			return nil, err
		}
	}
	patch := webhookToUpdatePatch(merged)
	patch.Etag = graphql.Value(repox.NewULID())
	if in.GetEtag() != "" {
		if _, err := r.Svc.Mutation.HooksV1.Webhooks.UpdateIfMatch(ctx, id, patch, webhooksql.Etag.Eq(in.GetEtag())); err != nil {
			return nil, mapGraphQLErr(err)
		}
		return r.get(ctx, id)
	}
	resp, err := r.Svc.Mutation.HooksV1.Webhooks.Update(ctx, id, patch)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return nil, repox.ErrNotFound
	}
	return r.get(ctx, id)
}

// newInput builds the insert a Batch queues for in, and
// the record it stands for, named: the same resolution Create applies.
func (r *GraphQLWebhookRepository) newInput(in *hooksv1.Webhook) (webhooksql.CreateInput, *hooksv1.Webhook, error) {
	var ci webhooksql.CreateInput
	id := repox.NewULID()
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "webhooks")
		if err != nil {
			return ci, nil, err
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*hooksv1.Webhook)
	in.Name = FormatWebhookName(id)
	ci = webhookToCreateInput(in)
	ci.Id = id
	ci.Etag = repox.NewULID()
	now := tsToStr(timestamppb.New(time.Now().UTC()))
	ci.CreateTime = now
	return ci, in, nil
}

// updateOps queues Update's writes onto ops, for a Batch: the value-object
// rows that replace the masked ones, the row update, then the removal of what
// they replaced. With in.Etag set the update is guarded inside the batch: a
// self-update of the key whose post-check asserts the etag fails the request
// when the record moved on, and the guarded update after it writes the row.
//
// outputPaths names the server-owned fields written alongside
// (Update<Model>WithOutputOnly); nil for Update.
func (r *GraphQLWebhookRepository) updateOps(ctx context.Context, ops *repox.Ops, id string, in *hooksv1.Webhook, paths, outputPaths []string) (repox.Check, error) {
	row, err := r.Svc.Query.HooksV1.Webhooks.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	existingPB := webhookFromRow(row)
	if in.GetEtag() != "" && existingPB.GetEtag() != in.GetEtag() {
		return nil, repox.ErrConflict
	}
	merged := proto.Clone(existingPB).(*hooksv1.Webhook)
	applyWebhookMask(merged, in, paths)
	patch := webhookToUpdatePatch(merged)
	patch.Etag = graphql.Value(repox.NewULID())
	var utx, atx repox.Ops
	*ops = append(*ops, utx...)
	resp := new(webhooksql.UpdateHooksV1WebhooksByIdResponse)
	etag := in.GetEtag()
	if etag != "" {
		ops.Add(r.Svc.Mutation.HooksV1.Webhooks.UpdateOp(id, webhooksql.UpdateInput{Id: graphql.Value(id)}, new(webhooksql.UpdateHooksV1WebhooksByIdResponse), webhooksql.Update().PostCheck(webhooksql.Etag.Eq(etag))))
		ops.Add(r.Svc.Mutation.HooksV1.Webhooks.UpdateOp(id, patch, resp, webhooksql.Update().PreCheck(webhooksql.Etag.Eq(etag))))
	} else {
		ops.Add(r.Svc.Mutation.HooksV1.Webhooks.UpdateOp(id, patch, resp))
	}
	*ops = append(*ops, atx...)
	return func(ctx context.Context, failed error) error {
		if failed == nil {
			if resp.AffectedRows == 0 {
				if etag != "" {
					return repox.ErrConflict
				}
				return repox.ErrNotFound
			}
			return nil
		}
		// The request failed; if this guard is why, say so.
		if etag != "" {
			if now, err := r.Svc.Query.HooksV1.Webhooks.Get(ctx, id); err == nil && (now == nil || webhookFromRow(now).GetEtag() != etag) {
				return repox.ErrConflict
			}
		}
		return nil
	}, nil
}

